const IMAGE_SELECTOR='img';

function normalizeImage(img){
  if(!img)return;

  const currentSrc=img.getAttribute('src');
  const dataSrc=img.dataset?.src;

  if((!currentSrc||currentSrc.trim()==='')&&dataSrc){
    img.src=dataSrc;
  }

  if(img.dataset?.src&&img.getAttribute('src')){
    delete img.dataset.src;
  }

  if(!img.hasAttribute('loading')){
    img.loading='lazy';
  }

  if(!img.hasAttribute('decoding')){
    img.decoding='async';
  }
}

function normalizeAllImages(root=document){
  root.querySelectorAll(IMAGE_SELECTOR).forEach(normalizeImage);
}

function removeDisabledSimulatorLinks(root=document){
  root.querySelectorAll('a[href*="visualizador-ar.html"]').forEach((link)=>{
    const item=link.closest('li');
    if(item)item.remove();
    else link.remove();
  });
}

function initializePage(root=document){
  normalizeAllImages(root);
  removeDisabledSimulatorLinks(root);
}

if(document.readyState==='loading'){
  document.addEventListener('DOMContentLoaded',()=>initializePage());
}else{
  initializePage();
}

window.restoreImageSources=normalizeAllImages;
